import numpy as np
def fit_pca(X, k):
    X = np.asarray(X, float)
    assert len(X) > 1 and 1 <= k <= min(X.shape)
    mean = X.mean(0)
    _, s, vt = np.linalg.svd(X - mean, full_matrices=False)
    return {"mean": mean, "axes": vt[:k], "variance": s[:k]**2/(len(X)-1)}
def transform_pca(X, model):
    return (X - model["mean"]) @ model["axes"].T

import numpy as np
def softmax(z):
    z = np.asarray(z, dtype=float)
    if not np.isfinite(z).all():
        raise ValueError("finite logits required")
    e = np.exp(z - z.max(axis=-1, keepdims=True))
    return e / e.sum(axis=-1, keepdims=True)

import torch
def sgd_step(parameters, lr):
    with torch.no_grad():
        for p in parameters:
            if p.grad is not None:
                p.add_(p.grad, alpha=-lr)
                p.grad = None

